INSERT INTO match_player_reports VALUES(21,162,'RCM','⚽ 57분 투입. 좌측 내부에서 공격 가담(실측 툴x 29.4).','슈팅 3(온타깃 1)·xG 0.13·태클 3·듀얼 4승 1패. 33분 만에 터치 23.','**평점 7.87(팀 3위) · 70분 결승골**(어시 한츠코).','wm_wideplm/Attack 0.805. ⛔ 표본 기준 미달(33분). ⚠️ 카를로스 마르틴(좌측 윙백)을 대체했으나 풀백으로 뛰지 않았다 — 57분에 구조가 바뀌었다.','FotMob matchDetails+heatmap matchId=5868012 (26/27 라리가 R1) · 원문 reports/match-watch/2026-08-19-atm-malaga.md · docs/13-simeone-tactics.md','[2026-08-20] ⚠️ **원천 FotMob**(SofaScore 사이트 전역 403 대체 경로). 좌표 방위는 실증 검증(오블락 cx=13 ⇒ 자기 골문 cx=0 · 다니 cy=9.1 ↔ 마르틴 cy=55.0 ⇒ 낮은 cy=우측). ⛔ **PPDA 없음**(WhoScored 미접근) — 압박 관련 판단의 신뢰도가 낮다. ⚠️ **표본 1경기**이고 ATM 확장 첫 경기다.');
INSERT INTO match_player_reports VALUES(21,163,'CDM','78분 투입. 코케의 중앙 배급 역할을 이어받았다.','12분 · 터치 13 · 정확패스 10.','평점 6.26. 표본이 거의 없다.','dm_dlp/Defend 0.714. ⛔ 표본 기준 미달(12분·히트포인트 14).','FotMob matchDetails+heatmap matchId=5868012 (26/27 라리가 R1) · 원문 reports/match-watch/2026-08-19-atm-malaga.md · docs/13-simeone-tactics.md','[2026-08-20] ⚠️ **원천 FotMob**(SofaScore 사이트 전역 403 대체 경로). 좌표 방위는 실증 검증(오블락 cx=13 ⇒ 자기 골문 cx=0 · 다니 cy=9.1 ↔ 마르틴 cy=55.0 ⇒ 낮은 cy=우측). ⛔ **PPDA 없음**(WhoScored 미접근) — 압박 관련 판단의 신뢰도가 낮다. ⚠️ **표본 1경기**이고 ATM 확장 첫 경기다.');
INSERT INTO match_player_reports VALUES(22,19,'GK','포스트를 지키는 정통 GK. 스윕 0회, 라인 유지형.','세이브 3회 전부 박스 안(다이빙 2). 하이클레임 1·펀치 1. 롱볼 8/20(40%)로 탈압박 기점 기능은 못 했다.','90′ · 6.51 · 실점 4 · xGOT 대면 2.83 · 실점 방지 -0.17 · 패스 17/29 · 터치 40 · 리커버리 7 · 클리어 2','gk_goalkeeper/Defend fit 0.961 — 슬롯 기하상 문제 없음. 4실점 중 막을 수 있었던 것은 사실상 없다(xGOT 2.83 대비 -0.17). 스즈키 대신 선발인 이유는 실측이 아니라 영입 시점(스즈키 이번 주 파르마에서 이적 완료, 구단 공식).','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,2,'RB','전진하지 않는 우측 풀백. 전진 패스는 넣지만 본인은 올라가지 않는다.','팀 최다 「최종 3선 패스 10」·라인브레이킹 8인데 **상대 박스 터치 0**. 지상 듀얼 4/5. 롱볼 2/7.','90′ · 5.34 · 태클 2 · 인터셉트 1 · 클리어 3 · 터치 49(팀 최다) · 파울 2 · 경고(90′)','fb_wingback/Balanced fit 0.951. avg_x 35.0 vs 마첸 44.5 — 우측 억제는 obs#4의 좌우 비대칭 문법과 정합이므로 역할 변경 근거가 아니다. 다음 경기 완비사카 투입 시 이 문법이 선수 교체로 바뀌는지가 재검증 항목.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,7,'RCB','우측 센터백. 위치는 정직, 듀얼에서 밀렸다.','자책골 1(8′). 구단 공식 서술로는 **본인 실책이 아니라 포스트 리바운드 유탄**이다. 그러나 듀얼 0/4(지상 0/1·공중 0/3)는 별개 문제.','90′ · **3.57** · 자책골 1 · 패스 26/33 · 클리어 3(헤더 2) · 리커버리 1 · 터치 38','cb_bpd/Aggressive fit 0.964 — 그리드는 이상적이다. 낮은 평점은 기하가 아니라 이벤트 결과이므로 역할 변경 근거로 쓰지 않는다.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,4,'LCB','좌측 센터백 겸 빌드업 기점. 좌측 터치라인까지 확장.','errors_led_to_goal 1(8′ 실점의 기점). 지상 듀얼 0/3 + 드리블 돌파 허용 2. 클리어 4(헤더 3)로 반응 수비는 했다.','74′ · **3.67** · 패스 20/26 · 인터셉트 1 · 최종 3선 패스 1 · 터치 34 · 74′ 밍스와 교체','cb_bpd/**Build-Up** fit 0.886 — 기하는 맞는데 이 경기 수행이 역할을 지지하지 않았다. 단일 경기로 정본 변경하지 않는다. 다음 경기 린델뢰프와의 조합 유지 여부가 판정점.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,6,'LB','유일하게 전진한 풀백. 좌측 폭을 혼자 담당.','그리드가 좌측 열에 몰리고 x=93까지 나갔다(avg_x 44.5로 백4 최고). 그러나 드리블 0/3·지상 2/7로 1대1이 전부 밀렸다. 패스 5/7(71%).','82′ · 4.82 · 클리어 5 · 인터셉트 2 · 태클 2 · 슛 1(xG 0.035, 52′ 사이드네트) · 터치 38 · 81′ 루헤리와 교체','fb_wingback/Balanced fit 0.792. 좌측 전진 자체는 유지 판정. Attack 계열 상향은 듀얼 수치(0/3·2/7)가 지지하지 않는다.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,12,'RDM','앵커. 1월 이후 첫 PL 출전.','패스 22/23(96%)로 거의 안 놓쳤는데 지상 듀얼 4/11(36%)·볼 소실 4로 대인에서 밀렸다. 상대 박스 터치 0.','90′ · 5.46 · 태클 2 · 인터셉트 1 · 슛 블록 1 · 리커버리 2 · 터치 38 · 파울 2','dm_holding/**Roaming** fit 0.824. Roaming인데 상대 진영 개입이 없었다(PPDA 분모 기여 미미) — 컨디션 맥락(1월 이후 첫 PL, 구단 공식)이 있어 단일 경기로 포커스 변경하지 않는다. D+N 자료로 재검증.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,56,'LDM','좌측 피벗. 구단 PL 데뷔전에서 40분 퇴장.','**40분만 뛰고 주행거리 681(팀 최다)·최고 속도 22.9** — 강도는 있었다. 태클 4·지상 6/9·패스 15/15(100%). 그러나 31′ 박스 안에서 탈취당해 4번째 실점, 40′ VAR 리뷰로 **폭력적 행위 다이렉트 레드**.','**40′** · **4.02** · errors_led_to_goal 1 · 경고(9′) + **퇴장(40′)** · 터치 26 · 클리어 1','표본 40분이고 본인이 10명 상태를 유발했다 ⇒ **역할 판정 보류**. dm_dlp/Roaming fit 0.783은 참고값. 이 경기를 그의 역할 근거로 쓰지 말 것.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,10,'RM','공칭 우측 공격 미드필더 · 실측은 훨씬 낮은 우측 미드필더. 주장.','**팀에서 가장 저항한 선수** — 지상 듀얼 7/12(팀 최다 승리)·파울 유도 4·수비 액션 6. 드리블 2/5. 최종 3선 패스 6. 그러나 상대 박스 터치 0.','82′ · 6.49 · 슛 1(xG 0.044, 17′) · 태클 1 · 인터셉트 1 · 클리어 1 · 터치 39 · 경고(33′) · 82′ 알리송과 교체','core.classify 자동 분류가 **RDM**을 준다 — 공칭 RM보다 훨씬 낮았다(avg_x 54.6). wm_widemid/**Build-Up** fit 0.852. 폭 유지는 되는데 최종 3선 진입이 본인 몸으로 이어지지 않았다.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,21,'CAM','중앙 공격 미드필더. 사전 예상 선발 명단에 없던 선택.','팀 내 찬스 생성 최다(2)·드리블 2/2 성공. 그리드가 **자기 진영과 상대 박스로 양극화**됐다(중간이 비었다). 볼 소실 4로 전환을 내줬다.','74′ · 6.02 · 슛 1(68′ 코너 헤더, xG 0.096 — 빌라 최후의 유효 기회) · 지상 4/8 · 공중 1/2 · 터치 39 · 74′ 보가르드와 교체','⚠️ cam_playmaker/Build-Up fit **0.486** — 매우 낮다. 자동 분류는 **LDM**(avg_x 48.5). CAM 슬롯 기하와 실측이 어긋났다. 이 자리를 바클리로 채우는 것 자체가 재검증 대상.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,30,'LM','좌측 미드필더. PL 첫 선발(유스, obs#126 명단).','**4-0에서도 90분 완주한 유일한 전방 선수.** 지상 4/5·공중 2/4·태클 3·드리블 1/1로 듀얼 승률이 좋고 **최고 속도 26.7로 팀 1위**. 패스 6/13(46%)는 압박 하 볼 처리 미숙. 좌측 열에 강하게 고정.','90′ · 6.48 · 찬스 생성 1 · 박스 터치 1 · 터치 23 · 주행거리 482','wm_widemid/Support fit **0.682** — 낮다. 폭은 지켰지만 좌측 터치라인 고정형이다. ⚠️ 19세·표본 1경기 ⇒ **처방 확정 금지**. player-collect 축으로 별도 수집 필요.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,14,'ST','공칭 최전방 · 실측은 좌측으로 흐르는 프리롤. 인정된 9번의 대행.','팀 최고 평점이자 **첫 7분 슛 3개의 주인**(4·5·7′). 그러나 **공중 2/9** — 9번 대행으로서 기준점 기능을 못 했다. avg_y 68.1은 최전방인데 중앙을 비웠다는 뜻이다. 수비 액션 8·인터셉트 2로 후방 가담은 했다.','86′ · **6.55(팀 최고)** · 슛 3(팀 최다, 전부 무유효) · xG 0.13 · xA 0.09 · 지상 4/6 · 박스 터치 2 · 터치 34 · 86′ 가르나초와 교체','⚠️⚠️ st_advanced/Support fit **0.388 — 이 경기 최저**. 자동 분류는 **LM**. 「부엔디아를 9번에 두는 것」은 실측·커널 어느 쪽도 지지하지 않는다. 단 이건 역할 문제가 아니라 **인선 문제**다 — 왓킨스 명단 제외·아브라함 doubtful·마조 9월 초로 가용 ST가 0명이었다.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured. ⚠️ 50분간 10명·점유 27% 조건의 값이다.');
INSERT INTO match_player_reports VALUES(22,17,'LCB','74′ 투입(파우 토레스 대체). 백라인 안정화.','터치 1. 태클 1·지상 1/1. 표본이 사실상 없다.','16′ · 6.17 · 터치 1 · 수비 액션 1','hit_points 1 ⇒ 그리드 무효. cb_wideback/Defend fit 0.435는 **hp 1의 산물이라 무의미**하다. 판정 유보.','FotMob matchDetails/shotmap matchId=5795369 (선수 스탯·평점·분·xG) · WhoScored matchCentreData(Opta) matchId=1983554 (좌표·듀얼·태클 원천) · avfc.co.uk 공식 매치리포트·팀뉴스(2026-08-23) · core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=1, pos)','measured(표본 미달). ⚠️ hit_points 15 미만 — 그리드·fit 값이 통계적으로 무의미하다. 리포트 근거로만 쓰고 시즌 집계·처방에 넣지 말 것.');
