INSERT INTO match_player_reports VALUES(24,163,'CDM','CDM(툴x 45.1) — 최저점 배급 축','이 팀의 배급 중심. 패스량·찬스창출 모두 팀 1위.','90'' 평점 7.0 · **키패스 5(팀 1위)** · 패스 66(정확 64) · 터치 82. ⚠️ **PK 헌납**(부차난을 넘어뜨림) · 76'' 경고. El Desmarque 4 ↔ ITC 6.','dm_dlp/Roaming .855 — 실측이 배급형을 지지한다. **선발 데뷔전**(R1은 교체 투입).','SofaScore API event 16416302 · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · D+1 서사: El Desmarque · Cuatro Picas · Nostresport · Demócrata/COPE · Infobae/EFE · Starnews·스포츠경향(한국어) · bold.dk(덴마크어) · Pulse Sports Nigeria · Into the Calderón/VAVEL(403·요약만) · 시메오네·이니고 페레스 회견','⚠️ 표본 2경기 · 76~90분 10명 경기 · PPDA 미수집 · R1/R2 원천 상이(Opta/SofaScore). ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
INSERT INTO match_player_reports VALUES(24,154,'LCM','LM(배열) / 실측 좌중앙','라인 사이 공간을 잘 찾는다. 전반 팀 유효슈팅 2개 중 1개(22분)가 그의 것.','45'' 평점 6.6 · 슈팅 2 · xG .084 · 툴x 38.2. ⭐ **부진 교체가 아니다** — El Desmarque 7·ITC 6.5로 두 매체 다 긍정.','cm_b2b/Balanced .746(LCM 기준). 하프타임 교체는 0-0에서의 공격 리프레시로 해석되나 **시메오네의 공식 설명은 없다 — 미해소.**','SofaScore API event 16416302 · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · D+1 서사: El Desmarque · Cuatro Picas · Nostresport · Demócrata/COPE · Infobae/EFE · Starnews·스포츠경향(한국어) · bold.dk(덴마크어) · Pulse Sports Nigeria · Into the Calderón/VAVEL(403·요약만) · 시메오네·이니고 페레스 회견','⚠️ 표본 2경기 · 76~90분 10명 경기 · PPDA 미수집 · R1/R2 원천 상이(Opta/SofaScore). ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
INSERT INTO match_player_reports VALUES(24,158,'LM','명목 우측 포워드 / 실측 좌측(툴x 30.0)','⚠️ 이 경기 최대 평가 격차. 쇠를로트 부상 + 알바레스 관리로 떠밀려 9번을 맡았다.','79'' 평점 7.3 · 키패스 2 · xA .202 · **유효슈팅 0**. VAVEL 6.5(「센터포워드 적응 중」) ↔ El Desmarque **3**(「자기 자리를 찾지 못했다」).','wm_insidefwd/Attack .751(LM 기준). ⚠️ 명목·매체는 둘 다 「중앙 9번」인데 실측만 좌측이다 — **설계된 로테이션이 아니라 표류**로 판정하되 좌측 편류는 실측 단독 근거다.','SofaScore API event 16416302 · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · D+1 서사: El Desmarque · Cuatro Picas · Nostresport · Demócrata/COPE · Infobae/EFE · Starnews·스포츠경향(한국어) · bold.dk(덴마크어) · Pulse Sports Nigeria · Into the Calderón/VAVEL(403·요약만) · 시메오네·이니고 페레스 회견','⚠️ 표본 2경기 · 76~90분 10명 경기 · PPDA 미수집 · R1/R2 원천 상이(Opta/SofaScore). ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
INSERT INTO match_player_reports VALUES(24,162,'ST','명목 좌측 포워드 / 실측 중앙(툴x 48.2)','루크만과 최전방 투톱 선발 → 후반 시작 바에나 투입과 함께 우측으로 이동(한국 매체).','66'' 평점 6.9 · **슈팅 6(팀 최다)** · **유효 0** · 키패스 2 · 볼로스트 0 · 패스 81%. ⚠️ 비자 문제로 합류 2주.','st_false9/Build-Up .573 — ⚠️ 낮다. 실측 중앙은 「전반 ST + 후반 RM」의 평균 혼합이라 단일 슬롯 적합이 과소평가된다.','SofaScore API event 16416302 · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · D+1 서사: El Desmarque · Cuatro Picas · Nostresport · Demócrata/COPE · Infobae/EFE · Starnews·스포츠경향(한국어) · bold.dk(덴마크어) · Pulse Sports Nigeria · Into the Calderón/VAVEL(403·요약만) · 시메오네·이니고 페레스 회견','⚠️ 표본 2경기 · 76~90분 10명 경기 · PPDA 미수집 · R1/R2 원천 상이(Opta/SofaScore). ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
