INSERT INTO match_player_reports VALUES(25,31,'GK','후방 골키퍼','패스보다 선방·세컨드볼 처리 비중이 큰 경기',unistr('선방 4회에도 goals prevented -0.78; 두 실점 개입이 불안했다.\u000a\u000a⚠️ [2026-08-25 D+1] **최저권 평가가 3중으로 굳었다** — Read Chelsea **4/10**, 그리고 복수 전술 기사가 **「킹의 선제골 대응이 「새 GK가 필요하다」는 논거를 키웠다」**로 적는다. 우리 실측 **goals prevented −0.78**과 방향이 정확히 같다 ⇒ **정형 지표·매체 평가·전술 서술 3중 정합**.'),'골 방어 안정 전까지 시즌 주전 GK 처방 승격 금지.','FotMob matchDetails matchId=5795372 (curl, 2026-08-25) — 라인업·득점·교체·팀/선수 스탯·xG·물리량 / WhoScored matchCentreData(Opta) matchId=1983550 이벤트 1659건 — 터치 좌표·5x5 그리드·PPDA / Chelsea FC 공식 리포트 · Guardian(Jonathan Wilson) · Sky Sports · El País · Cadena SER · AS (2026-08-24~25). / 리포트: reports/match-watch/2026-08-24-che-fulham.md · Guardian 분석 https://www.theguardian.com/football/2026/aug/24/premier-league-chelsea-xabi-alonso-fulham','measured+reported; 교체 5명은 45분 미만이며 hp15 미달 행의 적합 해석을 금지.');
INSERT INTO match_player_reports VALUES(25,63,'RCB','넓은 우측 커버 CB','클리어 7·회수 5와 전진 경합',unistr('90분 동안 우측 백3의 가장 안정적인 수비 수행.\u000a\u000a⭐ [2026-08-25 D+1] **전진의 근거가 구조로 설명된다** — 제임스의 백3 하강이 아체암퐁·라크루아 **두 CB를 함께** 전진하게 풀어 주는 설계다(Telegraph). 초판의 「넓은 우측 커버와 전진 경합을 동시에 수행」은 그 산출물이다.'),'RCB 공격적 BPD 후보이나 반복 표본 필요.','FotMob matchDetails matchId=5795372 (curl, 2026-08-25) — 라인업·득점·교체·팀/선수 스탯·xG·물리량 / WhoScored matchCentreData(Opta) matchId=1983550 이벤트 1659건 — 터치 좌표·5x5 그리드·PPDA / Chelsea FC 공식 리포트 · Guardian(Jonathan Wilson) · Sky Sports · El País · Cadena SER · AS (2026-08-24~25). / 리포트: reports/match-watch/2026-08-24-che-fulham.md · Guardian 분석 https://www.theguardian.com/football/2026/aug/24/premier-league-chelsea-xabi-alonso-fulham','measured+reported; 교체 5명은 45분 미만이며 hp15 미달 행의 적합 해석을 금지.');
INSERT INTO match_player_reports VALUES(25,130,'CCB','중앙 배급+기습 박스 침투 CB','패스 47/50, xA .20, 도움 1',unistr('박스까지 올라가 수비수를 벗기고 Rogers 골을 만들었다.\u000a\u000a⭐⭐ [2026-08-25 D+1] **전진이 단발이 아니라 설계였다.** 초판은 「예기치 않은 포지션 교환」으로 적었으나, **제임스가 백3로 내려가 자리를 메워 주기 때문에** 라크루아·아체암퐁이 올라갈 수 있는 구조다(Telegraph). 41분 득점 국면 구체: **높게 남아 파머의 패스를 받아** 로저스에게 컷백했다. ⇒ 초판 재검증 항목 #2(「설계된 반복 패턴인가 단발인가」)의 답은 **설계**다. ⚠️ 대가도 함께: 복수 매체가 「라크루아를 백3 중앙에 두고도 수비는 아쉬웠다」로 적는다.'),'알론소 체제의 자유 CB 패턴인지 다음 경기 확인.','FotMob matchDetails matchId=5795372 (curl, 2026-08-25) — 라인업·득점·교체·팀/선수 스탯·xG·물리량 / WhoScored matchCentreData(Opta) matchId=1983550 이벤트 1659건 — 터치 좌표·5x5 그리드·PPDA / Chelsea FC 공식 리포트 · Guardian(Jonathan Wilson) · Sky Sports · El País · Cadena SER · AS (2026-08-24~25). / 리포트: reports/match-watch/2026-08-24-che-fulham.md · Guardian 분석 https://www.theguardian.com/football/2026/aug/24/premier-league-chelsea-xabi-alonso-fulham','measured+reported; 교체 5명은 45분 미만이며 hp15 미달 행의 적합 해석을 금지.');
